"""Pages shared by the complete guide and the WhatsApp onboarding booklet."""

def append_meta_chapter(p, title, sub, steps, code, box, table, shot, link, start):
    n = start
    title(n, 'WhatsApp: do chip à API')
    p('Um roteiro para cadastrar <b>um número novo</b> na Meta, obter as chaves corretas e conectá-lo à <b>sua instalação Wabotia</b>. As telas reais foram conferidas em 06/11/2026. Alguns nomes aparecem em inglês.')
    table([['Etapa', 'Resultado esperado'], ['Preparar a empresa', 'Administrador, dados coerentes, portfólio e documentos disponíveis.'], ['Cadastrar o telefone', 'Linha própria confirmada por SMS ou ligação.'], ['Criar o app Meta', 'Integração ligada à conta de mensagens do atendimento.'], ['Preparar as chaves', 'Token de produção, App Secret e Verify Token guardados.'], ['Conectar ao Wabotia', 'Conta salva, webhook verificado e telefone encontrado.'], ['Testar', 'Mensagem real recebida, resposta e recibo conferidos.']])
    box('Este roteiro usa <b>Meta direto</b>. Não precisa de QR Code, WhatsApp Web nem WhatsApp instalado no Hermes. A operadora mantém a linha; a Meta opera o WhatsApp; a Cloudflare mantém o Wabotia. O Hermes executa os bots quando necessário.')
    p('<b>Já usa WhatsApp nesse número?</b> Não apague a conta para experimentar. Migração, coexistência com WhatsApp Business e número novo têm caminhos diferentes. Preserve os dados e avalie o fluxo compatível antes de mudar.')
    p(link('Roteiro online com as mesmas etapas', 'https://wabotia.queven.app/install#meta-whatsapp') + '<br/>' + link('Documentação oficial de introdução à Cloud API', 'https://developers.facebook.com/documentation/business-messaging/whatsapp/get-started/'), 'small')

    title(n+1, 'Prepare os requisitos')
    table([['Prepare', 'O que conferir'], ['Administrador', 'Conta legítima na Meta, acesso ao e-mail, desafios de segurança e autenticação de dois fatores. Não compartilhe senha.'], ['Empresa', 'Nome comercial, razão social, endereço, telefone e site coerentes. No Brasil, deixe CNPJ e documentos oficiais disponíveis para o que a Meta solicitar.'], ['Site', 'Página acessível, identificação e contato da empresa, política de privacidade adequada ao uso dos dados.'], ['Portfólio empresarial', 'Selecione a empresa correta no Business Suite. Tenha acesso suficiente para gerenciar os ativos.'], ['Número', 'Linha própria, com DDI/DDD e recebimento de SMS ou ligação. Não cadastre o chip novo no aplicativo WhatsApp antes deste roteiro.'], ['Wabotia', 'Instalação atualizada em HTTPS, administrador e perfil de atendimento. Use sua instalação, não a demonstração pública.'], ['Cobrança', 'Responsável por revisar tarifas e cadastrar o pagamento exigido pela Meta para uso pago. Custos Meta, operadora e Cloudflare são separados.']])
    box('Para receber o código, abra o aplicativo de <b>SMS</b> do celular ou atenda a ligação normal da operadora. O código não chega ao painel Wabotia e não exige cadastrar o número no WhatsApp do celular.')
    p('A Meta pode liberar testes antes da verificação e impor requisitos para produção ou escala. Os limites efetivos são os da sua conta. O teto de 20 do Wabotia não amplia o limite de números concedido pela Meta.', 'small')

    title(n+2, 'Empresa: confira a verificação')
    steps(['Abra <b>Meta Business Suite</b>, selecione o portfólio correto e entre em <b>Configurações > Informações da empresa</b>.', 'Confira nome, razão social, endereço, site e contato. Corrija divergências com os documentos antes de solicitar análise.', 'Localize <b>Status de verificação da empresa</b>. Se aparecer <b>Verificada</b>, não crie outra empresa para repetir o processo.', 'Se solicitado, abra <b>Central de Segurança</b>. Envie os documentos e confirme o vínculo com a empresa pelo método oferecido na própria Meta.', 'Acompanhe o resultado e eventuais pedidos de correção. Não há prazo universal de aprovação garantido pelo Wabotia.'])
    shot('34-meta-empresa-verificada.jpg', 'Recorte real de uma empresa verificada. Os dados cadastrais foram deixados fora da imagem.')
    sub('Não confunda estas etapas')
    table([['Verificação', 'O que significa'], ['Empresa', 'Confere a identidade e o vínculo com o negócio.'], ['Nome de exibição', 'Analisa o nome que será mostrado no telefone. É uma etapa separada.'], ['Meta Verified', 'Selo/assinatura; não substitui automaticamente os requisitos técnicos da API.'], ['Provedor de Tecnologia', 'Verificação de acesso para integrar ativos de outras empresas. É diferente de usar seus próprios números.']])

    title(n+3, 'Cadastre o perfil WhatsApp')
    steps(['No Business Suite, abra <b>Configurações > Contas > Contas do WhatsApp</b> e clique <b>Adicionar</b>.', 'Escolha <b>Criar conta do WhatsApp</b>. Neste roteiro, não escolha vincular o aplicativo WhatsApp Business existente.', 'Informe o <b>Nome de exibição do WhatsApp Business</b>. Use o nome comercial reconhecido pelo cliente, coerente com o site e a empresa.', 'Selecione a categoria real da atividade. Confira a foto e campos opcionais, se desejar.', 'Leia os termos. O responsável pela empresa deve concordar antes de continuar.'])
    shot('32-meta-tipo-conta.jpg', 'Menu real da Meta. A primeira opção inicia o cadastro de um número novo na plataforma.', width=430)
    box('O nome do perfil será visto pelo cliente e pode passar por análise. <b>Criar uma conta não aprova automaticamente o nome.</b> Não use nomes de terceiros, promessas de aprovação ou um nome sem relação com a empresa.')

    title(n+4, 'Confirme o seu telefone')
    steps(['Em <b>Escolha o número que deseja usar</b>, marque <b>Adicionar um novo número</b>. A opção Usar somente um nome de exibição não é o cadastro do chip deste roteiro.', 'Selecione <b>BR +55</b>. No campo do telefone, informe <b>DDD + número</b>, sem repetir o +55.', 'Escolha <b>SMS</b> ou <b>Ligação telefônica</b> e clique <b>Continuar</b>. Em telefone fixo, prefira ligação e confira se uma URA não impede o recebimento.', 'Digite os seis dígitos recebidos diretamente na tela da Meta. Não envie o código em chamados ou mensagens de suporte.', 'Clique <b>Avançar</b> e espere a conclusão da verificação.'])
    sub('Exemplo de preenchimento, com número fictício')
    table([['Campo', 'Como preencher'], ['País', 'BR +55'], ['Telefone', '11999990000'], ['Formato completo', '+55 (11) 99999-0000']])
    box('<b>O SMS não chegou?</b> Confira país, DDD, sinal, linha ativa e bloqueios de SMS/ligações internacionais. Aguarde o prazo da tela antes de reenviar ou trocar para ligação. Não repita pedidos rapidamente.')
    p('O código recebido é temporário. Ele comprova o controle da linha e <b>não é</b> o token da API, o Verify Token ou o PIN de seis dígitos que pode ser definido no registro da Cloud API.')

    title(n+5, 'Conta de mensagens e fuso')
    steps(['Depois da confirmação, a interface nova pode mostrar <b>Create a new Messaging account</b>.', 'Em <b>Account name</b>, use um nome reconhecível. Em <b>Time zone</b>, escolha o fuso da operação; neste exemplo, <b>(GMT-03:00) America/Sao Paulo</b>.', 'Leia os termos e conclua quando concordar. Espere <b>Conta do WhatsApp adicionada</b>.'])
    shot('35-meta-conta-mensagens.jpg', 'Tela real: a conta de mensagens organiza modelos e cobrança; o fuso precisa coincidir com o usado no Wabotia.')
    table([['Nome da tela', 'Para que serve'], ['Portfólio empresarial', 'Agrupa pessoas e ativos. Seu ID não é o WABA ID.'], ['Conta do WhatsApp / WAAC', 'Representa o perfil/telefone.'], ['Conta de mensagens', 'Organiza modelos e cobrança. Telas antigas usam WhatsApp Business Account ou WABA.'], ['Aplicativo Meta', 'Cadastro da integração, com permissões, App Secret e webhook.']])
    box('Para os próximos números do mesmo grupo, use <b>Adicionar telefone</b> na mesma conta pelo WhatsApp Manager ou pela Configuração da API. Não crie uma conta de mensagens separada para cada telefone de um grupo.')

    title(n+6, 'Crie o aplicativo da integração')
    steps(['Abra <b>developers.facebook.com/apps</b>. No primeiro acesso, conclua o cadastro de desenvolvedor solicitado pela Meta.', 'Clique <b>Criar aplicativo</b>, informe um nome como Wabotia Minha Empresa e um e-mail de contato acompanhado pela equipe.', 'Selecione <b>Conectar-se com clientes pelo WhatsApp</b>. Em Empresa, marque o portfólio correto.', 'Confira Requisitos e Visão geral. Leia os termos e clique <b>Criar aplicativo</b> quando concordar. Conclua pessoalmente a senha ou o desafio de segurança solicitado.'])
    shot('40-meta-app-criado.jpg', 'Painel real do aplicativo criado, com o caso de uso WhatsApp. A conta de mensagens é outra tela.')
    steps(['Confirme que o app aparece em <b>Meus apps</b>. No painel, abra <b>Personalizar o caso de uso WhatsApp > Configuração básica > Etapa 2. Configuração da produção</b>.', 'Expanda <b>Registre seu número de telefone do WhatsApp</b>. Confira a conta, o <b>Messaging Account ID</b> e a identificação do telefone. Se o número já aparece, não cadastre de novo.'])
    box('Na tela antiga, use <b>Início rápido > Começar a usar a API / Configuração da API</b>. Test Number é um telefone de teste da Meta, não seu chip. Confira o número real.')

    title(n+7, 'Cada chave tem um lugar')
    table([['Dado', 'Onde obter e onde usar'], ['ID da conta / WABA ID', 'Messaging Account ID na Configuração de produção, ou WABA ID na Configuração da API antiga. Use no Wabotia; não copie o ID do portfólio ou do app.'], ['Phone Number ID', 'ID específico do telefone na Meta. O roteador obtém na busca. Não é o número com DDI/DDD.'], ['Token Meta', 'Gerado para o usuário do sistema com acesso ao app e à conta. Cole no campo protegido Token Meta do Wabotia.'], ['App Secret', 'App Meta > Configurações > Básico > Chave secreta do aplicativo. Cole em App Secret. Valida a assinatura dos eventos.'], ['Verify Token', 'Você escolhe uma senha aleatória. Coloque exatamente igual no Wabotia e na configuração do webhook da Meta.'], ['PIN de seis dígitos', 'Você define para o registro/proteção do número na Cloud API. Guarde em local privado. Não é o código recebido por SMS.']])
    shot('41-meta-app-secret-oculto.jpg', 'Configurações do app > Básico. A chave continua oculta nesta imagem.', width=430)
    box('<b>Pause a gravação ao gerar, revelar ou copiar segredos.</b> Guarde em gerenciador de senhas ou arquivo privado protegido. Nunca publique tokens no manual, GitHub ou capturas. IDs identificam recursos; tokens e segredos autorizam operações.')
    p('Essas credenciais são diferentes de MASTER_KEY, SETUP_TOKEN, token Cloudflare e chave de integração Wabotia. Na edição de uma conta Wabotia, deixar um segredo vazio preserva o valor já salvo.', 'small')

    title(n+8, 'Gere o token de produção')
    steps(['No Business Suite, abra <b>Configurações > Usuários > Usuários do sistema</b>. Crie um usuário <b>Employee</b>, com nome simples como Wabotia.', 'Em <b>Atribuir ativos</b>, selecione somente o app da integração e a conta de mensagens do atendimento. Confira o alcance das permissões com o administrador.', 'Clique <b>Gerar token</b>, escolha o app e a validade. <b>60 dias</b> é a recomendação da Meta: anote o vencimento e troque antes dele.', 'Selecione <b>whatsapp_business_management</b> e <b>whatsapp_business_messaging</b>. Gere e guarde o token no local privado; cole no campo Token Meta do Wabotia.'])
    shot('42-meta-token-permissoes.jpg', 'Permissões antes de gerar o token. Nenhuma credencial aparece na captura.', width=400)
    p('Na tela atual, Apps > Gerenciar app e Contas de mensagens > Contas vinculadas > Tudo concedem o acesso. <b>Tudo também inclui usuários, configurações e informações de pagamento dessa conta.</b> Avalie o alcance; não selecione os demais ativos.', 'small')
    p('Para renovar, gere outro token no mesmo usuário/app e substitua só Token Meta no Wabotia. Valide a busca antes de revogar o antigo. O token temporário da tela de testes não é a credencial de produção.', 'small')

    title(n+9, 'Conectado não é nome aprovado')
    p('Abra <b>Gerenciador do WhatsApp > Números de telefone</b> e selecione a conta de mensagens. Confira o estado do número e do nome separadamente.')
    shot('38-meta-status-numero.jpg', 'Recorte real: o telefone aparece Conectado e com qualidade alta, enquanto o nome ainda está Em análise. O número foi omitido do recorte.')
    table([['Indicação', 'Como interpretar'], ['Código SMS confirmado', 'A Meta confirmou o controle da linha. Não comprova sozinho toda a integração.'], ['Conectado', 'O telefone está conectado na Meta. Ainda é necessário configurar token, webhook e conferir um teste real.'], ['Nome em análise', 'O nome de exibição passa por aprovação separada. Acompanhe o resultado.'], ['Qualidade e limites', 'Dependem da Meta e do uso. O Wabotia não amplia os limites concedidos.'], ['Pagamento pendente', 'Revise a cobrança da conta com o responsável antes do uso pago.']])
    box('Se o telefone já estiver conectado, <b>não refaça o registro nem redefina seu PIN</b> apenas para seguir uma receita. Se faltar registro Cloud API, consulte o roteiro da próxima página. Depois, volte à configuração normal.')
    p('Não cadastre novamente o mesmo número no WhatsApp pessoal ou Business do celular para testar este caminho. Use outro telefone como destinatário e remetente de teste.')

    title(n+10, 'Apoio: registro pela API Meta')
    p('Use somente se a Meta indicar que falta registrar o número na Cloud API. A verificação do SMS e esse registro são coisas diferentes. Se já aparece Conectado e a API funciona, pule esta etapa.')
    steps(['No Meta for Developers, abra <b>Ferramentas > Explorador da Graph API</b>. Use apenas a ferramenta oficial da Meta. Pause a gravação.', 'Selecione o aplicativo da integração e use seu <b>token de produção</b> no campo de token. Não use App Secret, Verify Token ou senha de login nesse lugar.', 'Selecione o método <b>POST</b>. No caminho, coloque o <b>Phone Number ID</b> seguido de <b>/register</b>. Mantenha uma versão de Graph API suportada pela sua conta.', 'Na área de parâmetros/corpo, adicione <b>messaging_product</b> com valor <b>whatsapp</b> e <b>pin</b> com um PIN de seis dígitos escolhido pelo responsável. Guarde esse PIN em local privado.', 'Confira novamente o telefone correspondente ao ID e envie uma vez. O retorno esperado é <b>success: true</b>. Volte ao WhatsApp Manager e confira o estado.'])
    code('Caminho: PHONE_NUMBER_ID/register\nMétodo: POST\n\nParâmetros:\nmessaging_product = whatsapp\npin = SEU_PIN_DE_SEIS_DIGITOS')
    box('O PIN acima é uma indicação de campo, não um valor para copiar. Não use 123456 ou o código SMS como PIN por conveniência. Se a resposta for ambígua, confira o estado antes de tentar de novo; não redefina credenciais para corrigir erros de token.')
    p(link('Documentação oficial de registro', 'https://developers.facebook.com/documentation/business-messaging/whatsapp/business-phone-numbers/registration'), 'small')

    title(n+11, 'Preencha sua conta no Wabotia')
    steps(['Abra a URL HTTPS da <b>sua instalação</b>, entre como administrador e selecione o perfil.', 'Abra <b>Roteador de números > Cadastrar ou editar a conta Meta</b>. Esse caminho permite começar com um só telefone.', 'Preencha nome, <b>ID da conta usado pela API / WABA ID</b>, fuso da conta Meta e os campos protegidos <b>Token Meta</b>, <b>App Secret</b> e <b>Verify Token</b>.', 'Clique <b>Salvar conta Meta</b> e aguarde a confirmação. Copie <b>Webhook único desta conta</b>.'])
    shot('30-router-conta.jpg', 'Referência do Wabotia com dados fictícios. Use o domínio da sua instalação, não o endereço local 127.0.0.1 da imagem.')
    box('Não cadastre o mesmo telefone em dois caminhos. O roteador usa <b>/webhooks/meta-accounts/...</b>; uma conexão individual tem outro caminho. Para adotar uma conexão antiga, pause e reconcilie as entregas primeiro.')

    title(n+12, 'Webhook: ligue o recebimento')
    steps(['Abra <b>Personalizar o caso de uso WhatsApp > Configuração básica > Etapa 2. Configuração da produção > Configurar webhooks</b>. Na tela antiga, procure WhatsApp > Configuração.', 'Em <b>URL de callback</b>, cole o endereço exibido pelo Wabotia. Use HTTPS público, sem login do Cloudflare Access na frente.', 'Em <b>Verificar token</b>, coloque o mesmo <b>Verify Token</b> salvo no Wabotia. Clique <b>Verificar e salvar</b> e espere a confirmação.'])
    shot('39-meta-webhook.jpg', 'Tela real com campos vazios. O aviso da Meta explica que o app precisa estar publicado para receber dados de produção.', width=470)
    p('Não coloque o token Meta nem o App Secret no campo Verificar token. Um evento fictício do botão Testar não comprova a entrega de uma mensagem real.', 'small')

    title(n+13, 'Inscreva a conta e publique o app')
    steps(['Assine o campo <b>messages</b> para receber mensagens e recibos. Ligações e grupos precisam dos eventos próprios quando habilitados.', 'No bloco <b>Registre seu número de telefone do WhatsApp</b>, ligue <b>Assinar webhooks</b> na conta correta. Assinar os campos e vincular a conta são etapas diferentes.', 'Abra <b>Publicar</b> no menu do aplicativo. Complete as pendências, incluindo as URLs públicas de privacidade e exclusão de dados quando solicitadas.', 'Use informações reais da sua empresa. A política deve descrever o tratamento de dados do atendimento e informar um contato responsável. Não invente URLs nem use a política de outra empresa.', 'Conclua os requisitos e publique o aplicativo. Confira o status <b>Publicado</b> antes do teste real.'])
    box('<b>Webhook verificado ainda não basta.</b> A Meta informa que aplicativos não publicados recebem somente eventos de teste do painel, sem dados de produção. Publicar o app não substitui a aprovação do nome do telefone.')
    sub('Se precisar conferir a inscrição pela API')
    p('Na ferramenta oficial Explorador da Graph API, com o app e o token corretos, faça <b>GET ID_DA_CONTA/subscribed_apps</b>. Procure o app esperado. Se faltar e esta for a integração desejada, <b>POST</b> no mesmo caminho inscreve o app do token. Confirme com GET. Não remova inscrições de outros sistemas sem avaliar o uso.')
    p('<b>Verificou, mas não recebe?</b> Confira app publicado, campo messages, inscrição da conta, App Secret correto, número ativo e perfil. O App Secret valida os eventos; Verify Token valida o desafio inicial.', 'small')

    title(n+14, 'Primeiro teste e próximos números')
    steps(['No Wabotia, clique <b>Buscar números na Meta</b>. Selecione o telefone real encontrado e dê um nome.', 'Confira e informe o uso de atendimento já realizado no mês. Zero somente se não houve uso. Confirme o fuso, o teto local e clique <b>Adicionar ao roteador</b>. O número entra pausado.', 'Revise na Meta: registro/conexão, nome, qualidade, limites e pendências da conta ou cobrança. Ative o número e o perfil quando estiver pronto para o teste.', 'De outro WhatsApp sob seu controle, envie uma mensagem ao novo número. Confira em <b>Conversas</b>, assuma o atendimento e responda.', 'Confira a resposta no celular e o recibo em <b>Entregas</b>. Depois teste anexos, queda/retomada e o bot, se for usar Hermes.', 'Para novos números do grupo, adicione-os à mesma conta de mensagens na Meta e repita a busca no Wabotia. Depois configure o grupo de roteamento.'])
    table([['Falha', 'Confira'], ['Busca vazia', 'ID da conta, conta selecionada no app, token e ativos do usuário do sistema.'], ['Recebe, mas não envia', 'Registro, permissão de mensagens, janela, limites e cobrança.'], ['Resposta duplicada', 'Outro sistema atendendo o mesmo número; pause e reconcilie o consumidor antigo.'], ['Na fila / sem confirmação', 'Acompanhe Entregas. Não repita criando um novo pedido sem conferir o anterior.']])
    box('Cadastro do número não autoriza mensagens pagas. Use modelo aprovado, consentimento do destinatário e <b>autorização explícita por envio</b>. Testes e capturas de tela não substituem a validação real da sua conta.')
    p(link('Grupos, contadores e API do roteador', 'https://wabotia.queven.app/install#roteador') + '<br/>' + link('Roteiro completo e fontes', 'https://github.com/Quevenapp/Wabotia/blob/main/docs/META-WHATSAPP.md'), 'small')
